import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import birdNames from "../data/bird-names.json"


interface PhotoNode {
  name: string
  relativeDirectory: string
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    photography: { nodes: PhotoNode[] }
  }
}

const FlightPathPage: React.FC<PageProps> = ({ data }) => {
  const [expandedIndex, setExpandedIndex] = React.useState<number | null>(null)
  const [containerHeight, setContainerHeight] = React.useState(0)
  const [showFloatingTop, setShowFloatingTop] = React.useState(false)
  const [dragY, setDragY] = React.useState(0)
  const [isDragging, setIsDragging] = React.useState(false)
  const [zoomScale, setZoomScale] = React.useState(1)
  const [zoomOrigin, setZoomOrigin] = React.useState({ x: 50, y: 50 })
  const initialPinchDistance = React.useRef(0)
  const lastScale = React.useRef(1)
  const touchStartY = React.useRef(0)
  const containerRef = React.useRef<HTMLDivElement>(null)

  const photos = React.useMemo(() => {
    const images = [...data.photography.nodes]

    // Fisher-Yates shuffle
    for (let i = images.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[images[i], images[j]] = [images[j], images[i]]
    }

    return images
  }, [data.photography.nodes])

  const getBirdName = (node: PhotoNode): string => {
    const galleryBirdNames = birdNames[node.relativeDirectory as keyof typeof birdNames] || {}
    return galleryBirdNames[node.name as keyof typeof galleryBirdNames] || ''
  }

  // Measure container height for SVG
  React.useEffect(() => {
    const measure = () => {
      if (containerRef.current) {
        setContainerHeight(containerRef.current.scrollHeight)
      }
    }
    measure()
    window.addEventListener('resize', measure)
    return () => window.removeEventListener('resize', measure)
  }, [expandedIndex])

  // Show floating back-to-top after scrolling down
  React.useEffect(() => {
    const onScroll = () => {
      setShowFloatingTop(window.scrollY > window.innerHeight)
    }
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  // IntersectionObserver for scroll-triggered reveal
  React.useEffect(() => {
    const cards = document.querySelectorAll('.flight-path__card')
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible')
            observer.unobserve(entry.target)
          }
        })
      },
      { threshold: 0.2 }
    )
    cards.forEach((card) => observer.observe(card))
    return () => observer.disconnect()
  }, [])

  // Build SVG path: sinusoidal curve snaking left-right
  const buildFlightPath = (): string => {
    if (!containerHeight) return ''
    const segHeight = containerHeight / photos.length

    let d = `M 30 0`

    for (let i = 0; i < photos.length; i++) {
      const y1 = i * segHeight + segHeight * 0.33
      const y2 = i * segHeight + segHeight * 0.66
      const yEnd = (i + 1) * segHeight

      if (i % 2 === 0) {
        d += ` C 20 ${y1}, 80 ${y2}, 70 ${yEnd}`
      } else {
        d += ` C 80 ${y1}, 20 ${y2}, 30 ${yEnd}`
      }
    }

    return d
  }

  return (
    <div className="container">
      <Header />

      <div className="flight-path__hero">
        <Link to="/photography" className="back-link">&larr; Back to Photography</Link>
        <h1>Flight Path</h1>
        <AccentDots />
      </div>

      <div className="flight-path__wrapper">
      <div className="flight-path__container" ref={containerRef}>
        {containerHeight > 0 && (
          <svg
            className="flight-path__line"
            viewBox={`0 0 100 ${containerHeight}`}
            aria-hidden="true"
          >
            <path d={buildFlightPath()} />
          </svg>
        )}

        <div className="flight-path__cards">
          {photos.map((node, index) => {
            const image = getImage(node.childImageSharp.thumb)
            if (!image) return null
            const birdName = getBirdName(node)

            return (
              <div
                key={`flight-${index}`}
                className="flight-path__card"
                onClick={() => setExpandedIndex(index)}
              >
                <GatsbyImage
                  image={image}
                  alt={birdName || `Bird photo ${index + 1}`}
                  className="flight-path__card-image"
                />
                {birdName && (
                  <div className="flight-path__card-name">{birdName}</div>
                )}
              </div>
            )
          })}
        </div>
      </div>
      </div>

      {expandedIndex !== null && (() => {
        const node = photos[expandedIndex]
        const image = getImage(node.childImageSharp.thumb)
        const birdName = getBirdName(node)
        const dismissThreshold = 120

        const getPinchDistance = (touches: React.TouchList) => {
          const dx = touches[0].clientX - touches[1].clientX
          const dy = touches[0].clientY - touches[1].clientY
          return Math.sqrt(dx * dx + dy * dy)
        }

        const handleTouchStart = (e: React.TouchEvent) => {
          if (e.touches.length === 2) {
            initialPinchDistance.current = getPinchDistance(e.touches)
            lastScale.current = zoomScale
          } else if (e.touches.length === 1 && zoomScale <= 1) {
            touchStartY.current = e.touches[0].clientY
            setIsDragging(true)
          }
        }

        const handleTouchMove = (e: React.TouchEvent) => {
          if (e.touches.length === 2) {
            const dist = getPinchDistance(e.touches)
            const scale = Math.max(1, Math.min(4, lastScale.current * (dist / initialPinchDistance.current)))
            const midX = ((e.touches[0].clientX + e.touches[1].clientX) / 2 / window.innerWidth) * 100
            const midY = ((e.touches[0].clientY + e.touches[1].clientY) / 2 / window.innerHeight) * 100
            setZoomScale(scale)
            setZoomOrigin({ x: midX, y: midY })
          } else if (e.touches.length === 1 && zoomScale <= 1) {
            const delta = e.touches[0].clientY - touchStartY.current
            if (delta > 0) {
              setDragY(delta)
            }
          }
        }

        const handleTouchEnd = () => {
          if (zoomScale <= 1) {
            setIsDragging(false)
            if (dragY > dismissThreshold) {
              setExpandedIndex(null)
              setZoomScale(1)
            }
            setDragY(0)
          }
        }

        const opacity = Math.max(0.2, 1 - dragY / 400)

        return (
          <div
            className="flight-path__spotlight"
            onClick={() => { setExpandedIndex(null); setZoomScale(1) }}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
            style={{ background: `rgba(0, 0, 0, ${opacity * 0.9})` }}
          >
            <div className="flight-path__spotlight-hint">Swipe down to close · Pinch to zoom</div>
            <div
              className="flight-path__spotlight-content"
              onClick={(e) => {
                e.stopPropagation()
                if (zoomScale > 1) {
                  setZoomScale(1)
                }
              }}
              style={{
                transform: `translateY(${dragY}px) scale(${zoomScale})`,
                transformOrigin: `${zoomOrigin.x}% ${zoomOrigin.y}%`,
                transition: isDragging ? 'none' : 'transform 0.3s ease',
              }}
            >
              {image && (
                <GatsbyImage
                  image={image}
                  alt={birdName || `Bird photo`}
                  className="flight-path__spotlight-image"
                />
              )}
              {birdName && (
                <div className="flight-path__spotlight-name">{birdName}</div>
              )}
            </div>
          </div>
        )
      })()}

      <div className="back-to-top-container">
        <button
          className="back-to-top"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
        >
          &uarr; Back to Top
        </button>
      </div>

      {showFloatingTop && (
        <button
          className="flight-path__floating-top"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          aria-label="Back to top"
        >
          &uarr;
        </button>
      )}

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query FlightPathPageQuery {
    photography: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { ne: "", nin: ["new-year-26"] }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        relativeDirectory
        childImageSharp {
          thumb: gatsbyImageData(
            width: 700
            placeholder: BLURRED
          )
        }
      }
    }
  }
`

export default FlightPathPage
